import{_ as t,o as e,a as l,d as o}from"./chunks/framework.IehvnstE.js";const p=JSON.parse('{"title":"Stuzhik Connect","description":"Stuzhik Connect — прямая P2P-передача модпаков и сборок между друзьями без серверов. Список друзей, коды подключения, VPN, безопасность.","frontmatter":{"description":"Stuzhik Connect — прямая P2P-передача модпаков и сборок между друзьями без серверов. Список друзей, коды подключения, VPN, безопасность.","head":[["meta",{"name":"keywords","content":"stuzhik connect, стужик коннект, передача модпака другу, p2p minecraft, обмен сборками minecraft, minecraft без сервера"}]]},"headers":[],"relativePath":"guide/connect.md","filePath":"guide/connect.md"}'),i={name:"guide/connect.md"};function r(n,a,s,h,d,c){return e(),l("div",null,[...a[0]||(a[0]=[o('<h1 id="stuzhik-connect" tabindex="-1">Stuzhik Connect <a class="header-anchor" href="#stuzhik-connect" aria-label="Permalink to &quot;Stuzhik Connect&quot;">​</a></h1><p>Забрать сборку или модпак у друга напрямую, без облака и без нашего сервера: файлы идут с его компьютера на ваш.</p><div class="warning custom-block"><p class="custom-block-title">Работает в пределах одной сети</p><p>Stuzhik находит устройства в одной сети: домашней, локальной или виртуальной, поднятой VPN-приложением. Своего сервера для соединения через интернет у Stuzhik нет, и если вы с другом в разных сетях (разные квартиры, города, провайдеры), напрямую вас почти всегда не пропустят домашние роутеры.</p><p>Один Wi-Fi или одна локалка: просто работает. Разные сети: нужен общий VPN, <a href="#если-вы-в-разных-сетях">см. ниже</a>.</p></div><div class="info custom-block"><p class="custom-block-title">Нужна версия 0.0.19 или новее, у обоих</p><p>С 0.0.19 Connect работает по новому протоколу (Connect 2), и лаунчеры 0.0.18 и старше с ним не соединяются вовсе: обновиться нужно обоим. Если рядом Stuzhik другой версии, панель состояния связи в разделе «Друзья» так и скажет.</p></div><h2 id="включение" tabindex="-1">Включение <a class="header-anchor" href="#включение" aria-label="Permalink to &quot;Включение&quot;">​</a></h2><ol><li>Откройте «Друзья» в боковой панели</li><li>Нажмите «Включить»</li><li>При первом включении лаунчер спросит, кто вас видит. По умолчанию никто: Connect включён, но для сети вас нет, пока не выберете «Только друзья» или «Все в сети» (<a href="#видимость">Видимость</a>)</li><li>Ваш код: <code>STUZHIK-XXXXXX</code>, 6 символов после префикса. Кнопка «Пригласить» копирует его</li></ol><h2 id="подключение-к-другу" tabindex="-1">Подключение к другу <a class="header-anchor" href="#подключение-к-другу" aria-label="Permalink to &quot;Подключение к другу&quot;">​</a></h2><h3 id="автопоиск" tabindex="-1">Автопоиск <a class="header-anchor" href="#автопоиск" aria-label="Permalink to &quot;Автопоиск&quot;">​</a></h3><p>В одной сети Stuzhik <strong>находит устройства сам</strong>: вводить ничего не нужно, друг появится в списке «Люди». Только он не должен быть «Невидим».</p><h3 id="по-коду" tabindex="-1">По коду <a class="header-anchor" href="#по-коду" aria-label="Permalink to &quot;По коду&quot;">​</a></h3><ol><li>Попросите у друга его код</li><li>Нажмите «Добавить устройство» и вставьте код</li><li>Подтвердите кнопкой «Добавить устройство»</li></ol><p>Код ищет друга той же рассылкой по сети, что и автопоиск: он нужен, чтобы попасть точно к нужному человеку, когда устройств в списке много. Поэтому и код работает <strong>только в одной сети</strong> (настоящей или VPN) и только если друг не «Невидим».</p><p>Код старого формата (4 символа) больше не принимается: у друга код обновится сам после обновления лаунчера.</p><h3 id="по-адресу" tabindex="-1">По адресу <a class="header-anchor" href="#по-адресу" aria-label="Permalink to &quot;По адресу&quot;">​</a></h3><p>Устройство не находится само (например, вы в Tailscale): «Добавить устройство» и адрес друга, <code>100.64.0.5</code> или <code>100.64.0.5:19848</code>. Порт можно не писать, подставится стандартный 19848: указывать его нужно, только если у друга Connect занял резервный порт.</p><h2 id="друзья" tabindex="-1">Друзья <a class="header-anchor" href="#друзья" aria-label="Permalink to &quot;Друзья&quot;">​</a></h2><p>Найденное устройство ещё не друг. Чтобы добавить:</p><ol><li>«⋯» у человека (или правая кнопка по нему) → «Добавить в друзья». После добавления по коду или адресу лаунчер предложит это сам</li><li>Друг принимает заявку у себя: она приходит во «Входящие» (колокол) и в список «Люди»</li><li>Готово: лаунчер узнаёт друга по подписи его ключом, и выдать себя за него нельзя</li></ol><p>Друзей лаунчер помнит вместе с адресами, до восьми на друга: локальная сеть, VPN, интернет. При включении Connect он сам стучится по всем запомненным адресам сразу, поэтому <strong>друг находится и там, где автопоиск не работает</strong>, и после того, как один из вас ушёл из общей локальной сети (<a href="#tailscale-и-другие-сети-без-широковещания">Tailscale</a>).</p><h3 id="проверить-связь" tabindex="-1">Проверить связь <a class="header-anchor" href="#проверить-связь" aria-label="Permalink to &quot;Проверить связь&quot;">​</a></h3><p>«Проверить связь» в карточке человека делает настоящее рукопожатие, то же, что перед передачей сборки, сразу по каждому известному адресу, и <strong>показывает итог для каждого адреса</strong>: «отвечает, N мс», «не отвечает», «другая версия Stuzhik» или «вы скрыты от него». Рядом с адресом видно, что это за сеть: локальная, Tailscale, Radmin VPN, Hamachi или интернет.</p><p>Проверить друга можно, даже когда он «не в сети»: если запомненный адрес ожил, друг сразу появится в списке.</p><p>Сервер, который друг открыл или на котором играет, виден в его комнате: задержка, сколько игроков онлайн, версия и сообщение сервера. «Зайти» ставит сборку сервера и подключает к нему: <a href="/guide/servers.html#friends-servers">Серверы друзей</a>.</p><h2 id="видимость" tabindex="-1">Видимость <a class="header-anchor" href="#видимость" aria-label="Permalink to &quot;Видимость&quot;">​</a></h2><p>Режим выбирается в настройках Connect:</p><table tabindex="0"><thead><tr><th>Режим</th><th>Кто вас видит</th></tr></thead><tbody><tr><td>Невидим</td><td><strong>Никто.</strong> Устройство не выходит в сеть вовсе: не отвечает никому и ничего о себе не объявляет. Друзья вас не найдут, только вы их</td></tr><tr><td>Только друзья</td><td><strong>Ник, сборки и во что вы играете видят только друзья.</strong> Само устройство заметно в сети всем (иначе друзья бы вас не нашли), но узнать в нём именно вас может только друг: опознавательная метка меняется каждые 10 минут и посторонним ничего не говорит</td></tr><tr><td>Все в сети</td><td><strong>Любой пользователь Stuzhik в этой сети</strong> видит вас в списке, с ником, если его показ включён</td></tr></tbody></table><p>Скрыться можно и от одного друга: «Скрыться от этого друга» в его меню. Для него вы «Невидим», остальные видят вас как обычно.</p><h2 id="профиль" tabindex="-1">Профиль <a class="header-anchor" href="#профиль" aria-label="Permalink to &quot;Профиль&quot;">​</a></h2><p>Своя карточка: «Мой профиль» → «Настроить», вкладка «Оформление». Другие видят её <strong>ровно такой, какой вы видите её у себя</strong>:</p><ul><li><strong>Баннер</strong>: живой эффект в шапке или на всю карточку и «Цвет баннера»</li><li><strong>Аватар</strong>: картинка обрезается до квадрата 256×256. «Фон под картинкой»: «Как обычно», свой цвет или «Прозрачный» (для PNG и WebP с прозрачным фоном)</li><li><strong>Рамки</strong>: отдельно для аватара и для всей карточки (линия, двойная, свечение, градиент и анимированные). «Цвет рамок»: как акцент или свой</li><li><strong>Акцент</strong> и строка «О себе»</li></ul><p>Цвет можно выбрать на квадрате, пипеткой с экрана или вставить строкой: <code>#4f8cff</code>, <code>rgb(79 140 255)</code>, <code>hsl(…)</code> или просто название цвета.</p><p>Кто видит оформление, решает «Оформление профиля видят» в настройках Connect: «Все, кому я виден» или «Только друзья». Ник и видимость в сети настраиваются отдельно.</p><h2 id="transfer" tabindex="-1">Передача сборок <a class="header-anchor" href="#transfer" aria-label="Permalink to &quot;Передача сборок {#transfer}&quot;">​</a></h2><p>Отправить сборку другу нельзя: <strong>Connect работает только «на забор»</strong>. Друг сам берёт сборку, а у вас лаунчер спрашивает разрешения, и в вопросе прямо написано, что друг хочет получить.</p><h3 id="открыть-сборку-друзьям" tabindex="-1">Открыть сборку друзьям <a class="header-anchor" href="#открыть-сборку-друзьям" aria-label="Permalink to &quot;Открыть сборку друзьям&quot;">​</a></h3><p><strong>По умолчанию сборки не опубликованы</strong>, для сети их нет. Открыть: правая кнопка по сборке (или «⋯») → «Публикация» → «Друзьям» или «Всем в сети». Чтобы друзьям было из чего выбрать, в настройках Connect должно быть включено «Показывать список модпаков».</p><p>Кто может просить сборку и спрашивать ли вас каждый раз, тоже решают настройки Connect. <strong>По умолчанию просить могут только друзья, и каждая передача идёт только с вашего согласия.</strong></p><h3 id="забрать-сборку-у-друга" tabindex="-1">Забрать сборку у друга <a class="header-anchor" href="#забрать-сборку-у-друга" aria-label="Permalink to &quot;Забрать сборку у друга&quot;">​</a></h3><ol><li>Карточка друга → «Сборки» → «Обновить», чтобы получить список</li><li>«Взять» у нужной сборки. Или «Взять сборку…» в меню друга: там сначала видно, что скачается, а что у вас уже есть</li><li>У друга появится вопрос «Запрос на передачу: … хочет получить от вас …». <strong>Файлы поедут, только когда он нажмёт «Разрешить»</strong></li></ol><p>Вопрос не пропадает по таймеру: он ждёт ответа, пока просящий на связи. Одно «Разрешить» действует на всю передачу, и если связь оборвётся, докачка не спросит заново. «Запомнить для этого пользователя» запоминает ответ для этого друга и этой сборки.</p><h3 id="во-время-передачи" tabindex="-1">Во время передачи <a class="header-anchor" href="#во-время-передачи" aria-label="Permalink to &quot;Во время передачи&quot;">​</a></h3><ul><li><strong>Прогресс</strong> в блоке передач раздела «Друзья», полный список в «Все передачи»</li><li><strong>Отмена</strong> там же, а у того, кто забирает сборку, ещё пауза и продолжение</li><li><strong>Только разница</strong>: передаются недостающие и изменившиеся файлы</li><li><strong>Обрыв связи</strong> не страшен: передача продолжится с того места, где остановилась</li><li><strong>Проверка</strong>: каждый скачанный файл сверяется по хешу, прежде чем лечь в сборку</li></ul><h2 id="coop-build" tabindex="-1">Совместная сборка <a class="header-anchor" href="#coop-build" aria-label="Permalink to &quot;Совместная сборка {#coop-build}&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Экспериментальная функция</p><p>Включается в Настройки → Эксперименты → «Экспериментальные функции». Пока она выключена, её нет нигде в интерфейсе.</p></div><p>Сборку можно собирать вместе с друзьями: хозяин открывает комнату, друзья заходят, предлагают и обсуждают моды, правят конфиги.</p><h3 id="открыть-комнату" tabindex="-1">Открыть комнату <a class="header-anchor" href="#открыть-комнату" aria-label="Permalink to &quot;Открыть комнату&quot;">​</a></h3><p>«Друзья» → «Собрать вместе» → своя сборка, «Новая сборка» (с нуля, друзья добавят моды сами) или проект из <a href="/guide/builder.html">Конструктора</a>. Там же «Кто сможет войти»:</p><ul><li><strong>«Друзья»</strong>: по умолчанию, только подтверждённые друзья</li><li><strong>«Все, кто меня видит»</strong>: незнакомцы только смотрят</li><li><strong>«По приглашению»</strong>: только отмеченные в настройках комнаты</li></ul><h3 id="в-комнате" tabindex="-1">В комнате <a class="header-anchor" href="#в-комнате" aria-label="Permalink to &quot;В комнате&quot;">​</a></h3><ul><li><strong>Роли.</strong> «Редактор» меняет состав сам, «Участник» выносит изменения на голосование, «Зритель» смотрит и обсуждает. Незнакомец всегда зритель. Роли и права (смотреть и править конфиги, голосовать, забирать сборку без вопроса, копировать комнату) хозяин задаёт в настройках комнаты</li><li><strong>Редактор сборки.</strong> «Открыть редактор сборки»: вкладки «Состав», «Каталог», «Совместимость», «Конфиги». Ставит моды только хозяин: правка участника это предложение, а сами файлы его лаунчер берёт с Modrinth и CurseForge</li><li><strong>Совместимость.</strong> «По составу» и «Граф зависимостей» доступны всем в комнате, ставить сборку для этого не нужно</li><li><strong>Предложения и обсуждение.</strong> Голосования, лента «Правки сборки» (изменение состава можно отменить) и «Обсуждение», общий чат комнаты</li></ul><h3 id="своя-копия" tabindex="-1">Своя копия <a class="header-anchor" href="#своя-копия" aria-label="Permalink to &quot;Своя копия&quot;">​</a></h3><p>«Забрать сборку» ставит себе копию сборки хозяина, а «Обновлять мою копию автоматически» догоняет его изменения. Свою комнату на основе чужой («Своя комната на основе этой») сделать можно, только если хозяин дал право «Копировать комнату»: по умолчанию его нет ни у кого.</p><p>Хозяин ушёл из сети: комната закрывается. Закреплённая комната («Закрепить комнату») вернётся сама, когда хозяин снова появится.</p><h2 id="если-вы-в-разных-сетях" tabindex="-1">Если вы в разных сетях <a class="header-anchor" href="#если-вы-в-разных-сетях" aria-label="Permalink to &quot;Если вы в разных сетях&quot;">​</a></h2><p>Домашние роутеры и мобильный интернет почти всегда блокируют прямое соединение между разными сетями. Так работает NAT: это не баг Stuzhik, и обойти это сами мы не можем. Рабочий вариант: <strong>общая виртуальная сеть</strong> поверх интернета. Вы оба ставите одно и то же VPN-приложение, оно объединяет ваши устройства в одну сеть, и Connect работает в ней.</p><p>Мы не разрабатываем и не поддерживаем эти приложения, это просто рекомендация того, что работает. Stuzhik не связан с этими сервисами и не распространяет их: здесь только названия, официальный сайт найдите через поисковик.</p><table tabindex="0"><thead><tr><th>Вариант</th><th>Сложность</th><th>Как находятся друзья</th></tr></thead><tbody><tr><td>Radmin VPN</td><td>Лёгкая</td><td>Сами, как в обычной локалке</td></tr><tr><td>ZeroTier</td><td>Средняя</td><td>Сами, когда вы оба в одной сети ZeroTier</td></tr><tr><td>Tailscale</td><td>Сложная</td><td>Один раз по адресу, дальше сами (<a href="#tailscale-и-другие-сети-без-широковещания">см. ниже</a>)</td></tr></tbody></table><p>Hamachi тоже собирает устройства в общую сеть, и поиск в нём работает сам. Подсказки по этим вариантам есть и в самом лаунчере, в разделе «Друзья» (тоже без ссылок, только названия).</p><p><strong>Через Steam.</strong> Если у вас обоих Steam, поиграть можно и через него (экспериментальная функция, включается в «Настройки → Steam»): откройте мир для сети, и у друзей в списке друзей Steam появится «Присоединиться». Их лаунчер подберёт или поставит ту же сборку и подключит к вам через сеть Steam, без открытых портов. Друзья видят вас в игре «Spacewar»: так называется тестовое приложение Steam, через которое это работает.</p><h3 id="tailscale-и-другие-сети-без-широковещания" tabindex="-1">Tailscale и другие сети без широковещания <a class="header-anchor" href="#tailscale-и-другие-сети-без-широковещания" aria-label="Permalink to &quot;Tailscale и другие сети без широковещания&quot;">​</a></h3><p>Tailscale и другие туннели уровня IP не передают широковещательные пакеты, поэтому автопоиск и код в них никого не находят. Друга нужно добавить <strong>по адресу, но только один раз</strong>:</p><ol><li>Узнайте у друга его адрес в Tailscale, вида <code>100.x.y.z</code></li><li>«Добавить устройство» → этот адрес. Порт можно не писать: по умолчанию 19848</li><li>Добавьте его в друзья, друг принимает заявку</li></ol><p><strong>Дальше всё само.</strong> После первого рукопожатия, в котором друг подтвердил себя подписью, лаунчер запоминает его адрес. При включении Connect и потом раз в 5 минут он стучится по запомненному адресу, а дозвонившись, держит друга в сети, пока тот отвечает. Друг, который достучался до вас сам, тоже появляется в списке. Комнаты совместных сборок, оформление профиля и «играет в …» доходят до такого друга так же, как по локальной сети.</p><p>Запоминаются только подтверждённые друзья. В режиме «Невидим» лаунчер не стучится никому, а к другу, от которого вы скрыты, никогда.</p><h2 id="брандмауэр" tabindex="-1">Брандмауэр <a class="header-anchor" href="#брандмауэр" aria-label="Permalink to &quot;Брандмауэр&quot;">​</a></h2><p>Connect работает <strong>только по UDP</strong>: поиск на порту 19847, соединения на 19848. Если порт занят другой программой, Connect берёт резервный (+10, +20 или +30).</p><p>На Windows для обоих портов нужно одно правило брандмауэра, «Stuzhik Connect». Его добавляет кнопка «Добавить правило брандмауэра» в разделе «Друзья» (Windows попросит разрешения). Правило из версий до 0.0.19 открывало передачу по TCP и теперь не помогает: экран связи это замечает и предлагает настроить правило заново. Нажмите «Добавить правило брандмауэра» ещё раз, новое заменит старое.</p><h2 id="безопасность" tabindex="-1">Безопасность <a class="header-anchor" href="#безопасность" aria-label="Permalink to &quot;Безопасность&quot;">​</a></h2><ul><li><strong>Шифруется всё.</strong> Соединения идут по QUIC с TLS 1.3 и шифруются целиком: файлы, каждое сообщение и само рукопожатие. Обмен ключами: гибрид X25519 и ML-KEM-768, ключи новые для каждого соединения</li><li><strong>Друга не подделать.</strong> Лаунчер узнаёт его по подписи ключом, привязанной к этому соединению: подслушанную подпись в другом соединении не предъявить</li><li><strong>Наблюдатель в той же сети</strong> видит факт соединения, его объём и то, что это Stuzhik, но не содержимое</li><li><strong>Без спроса ничего не заберут.</strong> Файлы уходят только после вашего «Разрешить». Так по умолчанию: в настройках выдачи «Спрашивать разрешение» можно переключить на «Кроме друзей» или «Никогда»</li><li><strong>Исполняемые файлы</strong> (<code>.exe</code>, <code>.bat</code>, <code>.ps1</code>, <code>.sh</code> и т.п.) не передаются никогда, даже с суффиксом <code>.disabled</code></li><li><strong>Заблокированный</strong> не может отправлять запросы и не виден в списке</li><li><strong>Публичный IP не сообщается.</strong> При знакомстве другу уходят только адреса домашней сети и VPN (Radmin, Tailscale, Hamachi), даже если компьютер подключён к интернету напрямую, без роутера</li></ul><h2 id="решение-проблем" tabindex="-1">Решение проблем <a class="header-anchor" href="#решение-проблем" aria-label="Permalink to &quot;Решение проблем&quot;">​</a></h2><h3 id="друг-не-находится-в-сети" tabindex="-1">Друг не находится в сети <a class="header-anchor" href="#друг-не-находится-в-сети" aria-label="Permalink to &quot;Друг не находится в сети&quot;">​</a></h3><ol><li>Оба включили Connect, и у обоих версия 0.0.19 или новее?</li><li>Друг не «Невидим»? В этом режиме его не найти никак</li><li>Вы точно в одной сети, физической или через общий VPN? VPN-приложение должно быть <strong>подключено у обоих</strong>, а не просто установлено</li><li>В Tailscale автопоиск не работает: добавьте друга по адресу (<a href="#tailscale-и-другие-сети-без-широковещания">см. выше</a>)</li><li>Брандмауэр: «Добавить правило брандмауэра» в разделе «Друзья»</li><li>Если вы уже друзья, «Проверить связь» в его карточке покажет, что именно не так</li></ol><h3 id="передача-зависла" tabindex="-1">Передача зависла <a class="header-anchor" href="#передача-зависла" aria-label="Permalink to &quot;Передача зависла&quot;">​</a></h3><ol><li>Посмотрите передачи в разделе «Друзья»: она может стоять на паузе</li><li>Продолжите её вручную</li><li>Не помогает: отмените и возьмите сборку заново. Передаются только недостающие и изменившиеся файлы</li></ol><h3 id="не-приходит-запрос-в-друзья" tabindex="-1">Не приходит запрос в друзья <a class="header-anchor" href="#не-приходит-запрос-в-друзья" aria-label="Permalink to &quot;Не приходит запрос в друзья&quot;">​</a></h3><ul><li>У друга в настройках Connect может быть выключено «Принимать заявки в друзья»: тогда заявки отбрасываются молча, и отправитель об этом не узнаёт</li><li>Друг «Невидим»: его не видно, и заявку отправить некуда</li><li>В режиме «Только друзья» незнакомцы видят вас без ника, как «Аноним». Чтобы друг точно нашёл именно вас, дайте ему свой код</li></ul><h2 id="что-дальше" tabindex="-1">Что дальше <a class="header-anchor" href="#что-дальше" aria-label="Permalink to &quot;Что дальше&quot;">​</a></h2><ul><li><a href="/guide/modpacks.html">Модпаки</a></li><li><a href="/guide/collections.html">Сборки модов</a></li><li><a href="/faq.html">FAQ</a></li></ul>',78)])])}const g=t(i,[["render",r]]);export{p as __pageData,g as default};
